#include <iostream>
#include <algorithm>
#include <cstring>
#include <vector>
#include <queue>
#include <complex>
#include <chrono>
#include <random>
#include <iomanip>
#include <cassert>

using namespace std;

using i64 = long long;
using f80 = long double;
using pii = pair<int, int>;

constexpr i64 INF_LIMIT = 0x3f3f3f3f;
constexpr i64 INF64_LIMIT = 0x3f3f3f3f3f3f3f3f;
constexpr i64 MOD_LIMIT = 1000000007;
constexpr f80 EPSILON = 1e-10;

mt19937_64 prng(chrono::steady_clock::now().time_since_epoch().count());

constexpr int TIME_HORIZON = 99;
constexpr int COST_LEVELS = 15;

struct FlowNetwork {
    static constexpr int MAX_NODES = 50 * TIME_HORIZON + 2;
    static constexpr int MAX_ARCS = 2 * MAX_NODES * COST_LEVELS + MAX_NODES + 7;

    int parent_node[MAX_NODES];
    int first_edge[MAX_NODES];
    int next_arc[2 * MAX_ARCS];
    int endpoint[2 * MAX_ARCS];
    int edge_count;

    i64 flow_val[2 * MAX_ARCS];
    i64 cap_val[2 * MAX_ARCS];
    i64 cost_val[2 * MAX_ARCS];

    bool vertex_visited[MAX_NODES];
    int queue_arr[MAX_NODES];
    int queue_pos[MAX_NODES];

    i64 dist_val[MAX_NODES];
    i64 pot_val[MAX_NODES];

    FlowNetwork() {
        reset_network();
    }

    void reset_network() {
        edge_count = 0;
        memset(first_edge, -1, sizeof(first_edge));
        memset(flow_val, 0, sizeof(flow_val));
    }

    void insert_edge(int u, int v, i64 capacity, i64 price = 0) {
        int idx = edge_count++;
        next_arc[idx] = first_edge[endpoint[idx] = u];
        first_edge[endpoint[idx]] = idx;
        cap_val[idx] = capacity;
        cost_val[idx] = price;

        idx = edge_count++;
        next_arc[idx] = first_edge[endpoint[idx] = v];
        first_edge[endpoint[idx]] = idx;
        cap_val[idx] = 0;
        cost_val[idx] = -price;
    }

    void setup_potentials(int num_vertices) {
        memset(pot_val, 0, sizeof(pot_val));
        for (int iter = 1; iter < num_vertices; ++iter) {
            for (int e = 0; e < edge_count; ++e) {
                if (cap_val[e]) {
                    pot_val[endpoint[e ^ 1]] = min(pot_val[endpoint[e ^ 1]], pot_val[endpoint[e]] + cost_val[e]);
                }
            }
        }
    }

    i64 update_flow(int source, int sink, i64& total_cost, int num_vertices) {
        memset(vertex_visited, 0, sizeof(vertex_visited));
        fill(dist_val, dist_val + num_vertices, INF_LIMIT);
        dist_val[source] = 0;
        memset(queue_pos, -1, sizeof(queue_pos));

        int head = 0, tail = 0;
        queue_pos[queue_arr[tail++] = source] = 0;

        while (head < tail) {
            int u = queue_arr[head++];
            queue_pos[u] = -1;

            for (int e = first_edge[u]; e != -1; e = next_arc[e]) {
                int v = endpoint[e ^ 1];
                if (flow_val[e] < cap_val[e] && dist_val[v] > dist_val[u] + pot_val[u] - pot_val[v] + cost_val[e]) {
                    dist_val[v] = dist_val[u] + pot_val[u] - pot_val[v] + cost_val[e];
                    parent_node[v] = e;

                    if (queue_pos[v] == -1) {
                        queue_pos[queue_arr[tail] = v] = tail;
                        tail++;
                    }

                    for (int i = queue_pos[v], p = (i - 1) / 2; i > 0 && dist_val[queue_arr[i]] < dist_val[queue_arr[p]]; 
                         i = p, p = (i - 1) / 2) {
                        swap(queue_arr[i], queue_arr[p]);
                        swap(queue_pos[queue_arr[i]], queue_pos[queue_arr[p]]);
                    }
                }
            }
        }

        if (dist_val[sink] >= INF_LIMIT) return 0;

        i64 augment = INF64_LIMIT;
        for (int node = sink; node != source; node = endpoint[parent_node[node]]) {
            augment = min(augment, cap_val[parent_node[node]] - flow_val[parent_node[node]]);
        }

        for (int node = sink; node != source; node = endpoint[parent_node[node]]) {
            int e = parent_node[node];
            flow_val[e] += augment;
            flow_val[e ^ 1] -= augment;
            total_cost += augment * cost_val[e];
        }

        for (int i = 0; i < num_vertices; ++i) {
            pot_val[i] = min((i64)INF_LIMIT, dist_val[i] + pot_val[i]);
        }

        return augment;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr); 
    cout.tie(nullptr);
    cout << fixed << setprecision(10);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    const int SOURCE = 0;
    const int SINK = n * TIME_HORIZON + 1;

    FlowNetwork flow_net;

    for (int i = 0; i < k; i++) {
        int a;
        cin >> a;
        flow_net.insert_edge(SOURCE, a, 1, 0);
    }

    for (int t = 0; t < TIME_HORIZON; t++) {
        flow_net.insert_edge(1 + t * n, SINK, INF_LIMIT, 0);
        if (t > 0) {
            for (int i = 1; i <= n; i++) {
                flow_net.insert_edge(i + (t - 1) * n, i + t * n, INF_LIMIT, c);
            }
        }
    }

    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        for (int j = 0; j < COST_LEVELS; j++) {
            int cost_coeff = (j + 1) * (j + 1) - j * j;
            for (int t = 1; t < TIME_HORIZON; t++) {
                flow_net.insert_edge(a + (t - 1) * n, b + t * n, 1, cost_coeff * d + c);
                flow_net.insert_edge(b + (t - 1) * n, a + t * n, 1, cost_coeff * d + c);
            }
        }
    }

    flow_net.setup_potentials(FlowNetwork::MAX_NODES);

    i64 total_cost = 0;
    i64 total_flow = 0;

    while (i64 augment = flow_net.update_flow(SOURCE, SINK, total_cost, FlowNetwork::MAX_NODES)) {
        total_flow += augment;
    }

    assert(total_flow == k);
    cout << total_cost << '\n';

    return 0;
}
